"""Executor: GPT-6 Astra via ``codex exec``. One thread per atomic task; resume drives the bounded fix loop.

Observed ``codex exec resume --help`` options (2026-09-19): ``--config``, ``--last``, ``--all``, ``--enable``,
``--disable``, ``--image``, ``--strict-config``, ``--model``, ``--dangerously-bypass-approvals-and-sandbox``,
``--dangerously-bypass-hook-trust``, ``--worktree``, ``--thread-source``, ``--skip-git-repo-check``, ``--ephemeral``,
``--ignore-user-config``, ``--ignore-rules``, ``--output-schema``, ``--json``, ``--output-last-message``, and ``--help``.
Notably, resume accepts ``--json`` and the access flags, but not ``-C``; its process cwd selects the worktree.
Usage-limit errors cool Codex down and hold the task (§4.10).
"""
import inspect, json, re, subprocess, time
from pathlib import Path
from . import ROOT, bus
import threading
from . import scorecard, allocation, critical_path, duration, jev_route, decision_log
from .pool import Pool, fallback_tier, is_rate_limited, parse_reset_hint

MAX_ROUNDS = 5
FALLBACK_JOIN_TIMEOUT_S = 5
_fallback_threads = []
_fallback_threads_lock = threading.Lock()


def _prune_fallback_threads():
    """Drop completed fallback workers while holding the registry lock."""
    _fallback_threads[:] = [thread for thread in _fallback_threads if thread.is_alive()]


def fallback_threads():
    """Return the currently running Claude fallback worker threads."""
    with _fallback_threads_lock:
        _prune_fallback_threads()
        return tuple(_fallback_threads)


def join_fallback_threads(timeout=FALLBACK_JOIN_TIMEOUT_S):
    """Wait a bounded time for fallback workers, returning those still alive."""
    deadline = time.monotonic() + timeout
    for thread in fallback_threads():
        thread.join(max(0, deadline - time.monotonic()))
    return fallback_threads()


def argv_for(kind, args, cwd, access):
    """Return a Codex argv without spawning it; fresh exec preserves its historical byte shape."""
    if kind == "exec":
        return ["codex", "exec", *args, "--json", "-C", str(cwd), *access]
    if kind == "resume":
        resume_access = []
        i = 0
        while i < len(access):
            flag = access[i]
            if flag == "--dangerously-bypass-approvals-and-sandbox":
                resume_access.append(flag)
            elif flag in ("-s", "--sandbox") and i + 1 < len(access):
                i += 1
                resume_access.extend(["--config", f'sandbox_mode="{access[i]}"'])
            i += 1
        return ["codex", "exec", "resume", *args, "--json", *resume_access]
    raise ValueError(f"unknown codex command kind: {kind}")


def parse_events(lines):
    """codex exec --json: newline-delimited events. Observed: thread.started{thread_id}, turn.started, error{message},
    turn.failed{error}, item.completed{item}, turn.completed{usage}. Unknown types are ignored."""
    out = {"thread_id": None, "message": "", "usage": {}, "error": None}
    for l in lines:
        l = l.strip()
        if not l.startswith("{"):
            continue
        try:
            e = json.loads(l)
        except json.JSONDecodeError:
            continue
        t = e.get("type", "")
        if t == "thread.started":
            out["thread_id"] = e.get("thread_id")
        elif t == "error":
            out["error"] = e.get("message")
        elif t == "turn.failed":
            out["error"] = (e.get("error") or {}).get("message", out["error"])
        elif t == "turn.completed":
            out["usage"] = e.get("usage", {})
        elif t == "item.completed" and (e.get("item") or {}).get("type") == "agent_message":
            out["message"] = e["item"].get("text", "")
    return out


def _tokens(u):
    """Codex reports cached_input_tokens, Claude cache_read_input_tokens. Write the Claude key so cli.cost aggregates
    both providers uniformly; keep the Codex key for one release so older runs/*.jsonl readers keep working."""
    out = {k: u.get(k, 0) for k in ("input_tokens", "output_tokens", "cached_input_tokens")}
    out["cache_read_input_tokens"] = out["cached_input_tokens"]
    out.update(bus.normalize_usage("codex", u))
    return out


def _state_target(task):
    """Return the task whose execution state belongs to this run."""
    return task.get("_run_task_id", task["id"])


def _run(pool, task, args, cwd, timeout, ex=None):
    cfg = pool.cfg["codex"]
    # dangerous_full_access (pool.toml): user decision 2026-09-16; otherwise workspace-write sandbox (container-safe default)
    access = ["--dangerously-bypass-approvals-and-sandbox"] if cfg.get("dangerous_full_access") else ["-s", "workspace-write"]
    kind = "resume" if args and args[0] == "resume" else "exec"
    command_args = args[1:] if kind == "resume" else args
    cmd = argv_for(kind, command_args, cwd, access)
    log_task = _state_target(task)
    log = {"executor": ex.id if ex else "codex", "complexity": task["complexity"]}
    constraints = task.get("_run_constraints", task.get("constraints") or {})
    if constraints.get("fix_round_for"):
        log["resume_mode"] = task.get("_resume_mode", "fresh")
    log["prompt_chars"] = len(args[-1])
    from .spawn import packet_run_meta
    log["packet_meta"] = task.get("packet_meta") or packet_run_meta(packet_span(args[-1]))
    t0 = time.time()
    try:
        run_kwargs = {"capture_output": True, "text": True, "timeout": timeout}
        if kind == "resume":
            run_kwargs["cwd"] = cwd
        r = subprocess.run(cmd, **run_kwargs)
    except subprocess.TimeoutExpired:
        return {"status": "failed", "reason": f"timeout after {timeout}s"}
    if r.returncode == 2 and ("unexpected argument" in r.stderr or "Usage:" in r.stderr):
        reason = f"codex argv error: {r.stderr[-800:]}"
        bus.log_run(task=log_task, role="execute", tier=log["executor"], account="codex",
                    duration_s=round(time.time() - t0, 1), outcome="failed", reason=reason, **log)
        bus.update(_state_target(task), resume_hint={"argv_error": reason[:300]})
        return {"status": "failed", "reason": reason}
    ev = parse_events(r.stdout.splitlines() + r.stderr.splitlines())
    if ev["thread_id"]:
        # The head is a resume boundary, not merely result metadata: later replies must not
        # expose an old conversation to unrelated worktree changes.
        fields = {"codex_thread": ev["thread_id"]}
        head = _thread_head(cwd)
        if head:
            fields["codex_thread_head"] = head
        bus.update(task["id"], **fields)
    if ev["error"] and is_rate_limited(ev["error"]):
        secs = parse_reset_hint(ev["error"], pool.cfg["limits"]["cooldown_default_s"])
        if ex:
            pool.cooldown_executor(ex.id, secs, "codex usage limit")   # a usage limit is the quota group's, not one model's
        pool.codex.cooldown_until = time.time() + secs; pool.save()
        bus.update(_state_target(task), status="held", hold_reason=f"codex usage limit; resets in {secs // 60} min",
                   resume_hint={"thread": ev["thread_id"], "diff_stat": _diff_stat(cwd)})
        bus.log_run(task=log_task, role="execute", tier=log["executor"], account="codex", outcome="usage_limit",
                    cooldown_s=secs, **log)
        return {"status": "held", "reason": ev["error"], "resets_in_s": secs}
    u = ev["usage"]
    bus.log_run(task=log_task, role="execute", tier=log["executor"], account="codex", provider="codex", duration_s=round(time.time() - t0, 1),
                outcome="error" if ev["error"] else "done", usage=u, **log, **(_tokens(u) if u else {}))
    if ev["error"] or r.returncode:
        return {"status": "failed", "reason": ev["error"] or r.stderr[-800:], "thread": ev["thread_id"]}
    return {"status": "done", "thread": ev["thread_id"], "message": ev["message"][:6000], "usage": u}


def _diff_stat(cwd):
    return subprocess.run(["git", "diff", "--stat"], cwd=cwd, capture_output=True, text=True).stdout[-1500:]


def _thread_head(cwd):
    r = subprocess.run(["git", "rev-parse", "HEAD"], cwd=cwd, capture_output=True, text=True)
    return r.stdout.strip() if r.returncode == 0 else None


def _resume_compatible(task):
    """A resumed thread may only see a clean descendant of its prior checkout head."""
    expected = task.get("codex_thread_head")
    cwd = task.get("worktree")
    if not cwd:
        return False, "worktree unavailable"
    # Tasks created before thread heads were recorded retain their historical resume behaviour.
    if not expected:
        return True, "legacy thread has no recorded head"
    status = subprocess.run(["git", "status", "--porcelain"], cwd=cwd, capture_output=True, text=True)
    if status.returncode or status.stdout.strip():
        return False, "worktree is dirty"
    head = _thread_head(cwd)
    ancestor = subprocess.run(["git", "merge-base", "--is-ancestor", expected, "HEAD"], cwd=cwd,
                              capture_output=True, text=True)
    return (bool(head and ancestor.returncode == 0), "worktree head moved" if head else "worktree HEAD unavailable")


def resume_plan(parent, fix_task):
    """Return the single authoritative routing decision for a fix round."""
    if not parent.get("codex_thread"):
        return {"mode": "fresh", "reason": "no_thread"}
    if parent.get("rounds", 0) >= MAX_ROUNDS:
        return {"mode": "fresh", "reason": "rounds_exhausted"}
    ex = Pool().executors.get(parent.get("executor") or "")
    if ex is None or ex.provider != "codex":
        return {"mode": "fresh", "reason": "executor_not_codex"}
    compatible, _ = _resume_compatible(parent)
    if not compatible:
        return {"mode": "fresh", "reason": "incompatible_worktree"}
    return {"mode": "resume", "reason": None}


def _commit_from_message(message):
    """Extract an explicitly reported commit, avoiding incidental short hexadecimal text."""
    full = re.search(r"\b[0-9a-f]{40}\b", message, re.I)
    if full:
        return full.group(0)
    labelled = re.search(
        r"\b(?:commit\s+sha|committed|commit|sha|HEAD\s+is\s+now\s+at)\b(?:\s*[:=]\s*|\s+)([0-9a-f]{7,40})\b",
        message, re.I,
    )
    if labelled:
        return labelled.group(1)
    backticked = re.search(r"\bCommit\b[^\n`]*`([0-9a-f]{7,40})`", message, re.I)
    return backticked.group(1) if backticked else None


def post_tool_result(task_id, result, replace_result=False):
    """Post a Codex result; fix-loop replies replace an unmerged task's prior round."""
    task = bus.get(task_id)
    if task.get("assigned_to") != "codex":
        return False, f"task is assigned to {task.get('assigned_to')}, not codex"
    if result.get("status") != "done":
        return False, f"codex result status is {result.get('status')}, not done"
    previous = task.get("result")
    if task.get("merged_into") is not None:
        return False, f"task is merged into {task.get('merged_into')}"
    if not replace_result:
        if previous is not None:
            return False, f"result exists from thread {previous.get('thread', 'unknown')}"
        if task.get("status") != "running":
            return False, f"task status is {task.get('status')}, not running"
    message = result.get("message", "")
    commit = _commit_from_message(message) or subprocess.run(
        ["git", "rev-parse", "HEAD"], cwd=task["worktree"], capture_output=True, text=True, check=True
    ).stdout.strip()
    posted = {
        "summary": message[:3000],
        "commit": commit,
        "executed_by": "codex:" + task["executor"],
        "provenance": ["repo"],
        "usage": result.get("usage"),
        "thread": result.get("thread") or task.get("codex_thread"),
        "rounds": (previous.get("rounds", 1) + 1) if replace_result and previous else 1,
    }
    if replace_result and previous:
        posted["previous_commits"] = [*previous.get("previous_commits", []), previous.get("commit")]
    with bus.locked():
        if replace_result:
            pipeline = dict(bus.get(task_id).ge

"""Task bus: SQLite hot index + one JSON file per task (git-backed via the orchestrator-state worktree)."""
import atexit, contextlib, fcntl, hashlib, json, sqlite3, subprocess, threading, time
from datetime import date
from pathlib import Path
from . import ROOT, STATE

TASKS = STATE / "tasks"
RUNS = STATE / "runs"
MAX_RESULT_CHARS = 6000  # ~1,500 tokens
ROLES = {"scout", "triage", "execute", "review", "challenge", "spec_review"}
STATUSES = {"queued", "held", "running", "done", "failed"}


LOCK_NAME = "bus.lock"
LOCK = STATE / LOCK_NAME
_held = threading.local()


@contextlib.contextmanager
def locked():
    """Serialize bus writes across the daemon, its worker threads and the Planner: an flock on .orchestrator/bus.lock,
    the same pattern as merge.lock. Reentrant per thread — flock keys on the open file description, so update() ->
    _save() opening the lock a second time would block on itself without the depth counter."""
    depth = getattr(_held, "depth", 0)
    if depth:
        _held.depth = depth + 1
        try:
            yield
        finally:
            _held.depth = depth
        return
    STATE.mkdir(parents=True, exist_ok=True)
    with open(LOCK, "w") as fh:
        fcntl.flock(fh, fcntl.LOCK_EX)
        _held.depth = 1
        try:
            yield
        finally:
            _held.depth = 0


_connection = None
_connection_path = None
_connection_lock = threading.Lock()


def _close_db():
    global _connection, _connection_path
    if _connection is not None:
        _connection.close()
        _connection = None
        _connection_path = None


atexit.register(_close_db)


def db():
    global _connection, _connection_path
    with _connection_lock:
        path = STATE / "bus.sqlite"
        if _connection is None or _connection_path != path:
            _close_db()
            STATE.mkdir(exist_ok=True); TASKS.mkdir(exist_ok=True)
            # The daemon and its worker threads share the cache; writes use locked().
            c = sqlite3.connect(path, isolation_level=None, check_same_thread=False)
            try:
                c.execute("create table if not exists tasks(id text primary key, status, role, tier, assigned_to, updated real)")
                c.execute("create table if not exists events(seq integer primary key autoincrement, task_id, ts real, kind, data)")
            except BaseException:
                c.close()
                raise
            _connection, _connection_path = c, path
        return _connection


def _save(t):
    with locked():
        TASKS.mkdir(parents=True, exist_ok=True)
        (TASKS / f"{t['id']}.json").write_text(json.dumps(t, indent=2) + "\n")
        db().execute("insert or replace into tasks values(?,?,?,?,?,?)",
                     (t["id"], t["status"], t["role"], t["tier"], t.get("assigned_to"), time.time()))


def _event(tid, kind, data=None):
    db().execute("insert into events(task_id,ts,kind,data) values(?,?,?,?)", (tid, time.time(), kind, json.dumps(data or {})))


def get(tid):
    p = TASKS / f"{tid}.json"
    if not p.exists():
        raise KeyError(tid)
    return json.loads(p.read_text())


def next_id():
    ids = sorted(int(p.stem[2:]) for p in TASKS.glob("T-*.json")) if TASKS.exists() else []
    return f"T-{(ids[-1] + 1) if ids else 1:04d}"


def create_task(title, spec, acceptance, scope, role="scout", tier="sonnet", complexity=3,
                parent=None, inputs=None, constraints=None, depends_on=None):
    """Planner-only. Mirrors the require-acceptance hook: no acceptance or scope -> rejected."""
    if role not in ROLES:
        raise ValueError(f"role must be one of {sorted(ROLES)}")
    if not acceptance or not scope:
        raise ValueError("acceptance and scope must be non-empty lists")
    tid = next_id()
    deps = list(depends_on or [])
    for dep in deps:
        if dep == tid:
            raise ValueError(f"task cannot depend on itself: {dep}")
        try:
            get(dep)
        except KeyError:
            raise ValueError(f"depends_on references unknown task: {dep}")
    t = {"id": tid, "created_at": time.time(), "parent": parent, "role": role, "tier": tier, "complexity": complexity,
         "title": title, "spec": spec, "inputs": inputs or [], "acceptance": list(acceptance), "scope": list(scope),
         "depends_on": deps,
         "constraints": {"read_only": role != "execute", "budget_turns": 20, "timeout_s": 900, **(constraints or {})},
         "status": "queued", "assigned_to": None, "worktree": None, "codex_thread": None, "result": None, "events": []}
    _save(t); _event(t["id"], "created")
    return t


def update(tid, **fields):
    """Non-Planner fields only: status, assigned_to, worktree, codex_thread, executor, pid, resume_hint.
    executor is the routed model id ("astra", "luna", ...) or "claude:<tier>" for a Claude fallback run."""
    with locked():   # read-modify-write: without the lock a concurrent update drops the other's fields
        t = get(tid)
        for k, v in fields.items():
            if k in {"spec", "acceptance", "scope", "complexity", "depends_on"}:
                raise PermissionError(f"only the Planner may set {k}; create a new task instead")
            t[k] = v
        t["events"].append({"ts": time.time(), **fields})
        _save(t); _event(tid, "update", fields)
    return t


def ready(task_or_id):
    """True iff every depends_on task is merged (merged_into set), or done for non-execute roles."""
    t = task_or_id if isinstance(task_or_id, dict) else get(task_or_id)
    for dep_id in t.get("depends_on", []):
        dep = get(dep_id)
        if dep.get("merged_into"):
            continue
        if dep["role"] != "execute" and dep["status"] == "done":
            continue
        return False
    return True


def dependents(tid):
    """Tasks that declare tid in their depends_on."""
    return [t for t in read() if tid in t.get("depends_on", [])]


def claim(tid, assigned_to, worktree=None):
    return update(tid, status="running", assigned_to=assigned_to, worktree=worktree, claimed_at=time.time())


def post_result(tid, result, status="done"):
    """Results are structured JSON, capped at ~1,500 tokens; oversize is rejected so the Planner's context stays small."""
    if status not in STATUSES:
        raise ValueError(f"status must be one of {sorted(STATUSES)}")
    if len(json.dumps(result)) > MAX_RESULT_CHARS:
        raise ValueError(f"result exceeds {MAX_RESULT_CHARS} chars; compress it (summary + artifact paths, not transcripts)")
    result.setdefault("confidence", 0.0); result.setdefault("provenance", ["repo"])
    return update(tid, status=status, result=result)


def _truncate(s, n):
    return s[:n] if isinstance(s, str) else s


def _compact_row(t):
    """A skimmable summary of one task: no spec, events, acceptance or scope, which is most of what makes the
    full shape big. See bus_mcp.bus_read for the field list."""
    result = t.get("result") or {}
    summary = result.get("summary")
    return {
        "id": t["id"], "parent": t.get("parent"), "role": t.get("role"), "status": t.get("status"),
        "complexity": t.get("complexity"), "tier": t.get("tier"), "title": _truncate(t.get("title"), 90),
        "depends_on": t.get("depends_on", []), "hold_reason": t.get("hold_reason"),
        "reason": _truncate(t.get("reason"), 120), "merged_into": t.get("merged_into"),
        "assigned_to": t.get("assigned_to"), "has_result": bool(t.get("result")),
        "result_summary": _truncate(summary, 160) if summary else None,
    }


def read(tid=None, status=None, status_not=None, role=None, compact=False):
    if tid:
        return get(tid)
    rows = db().execute("select id from tasks order by id").fetchall()
    out = [get(r[0]) for r in rows]
    filtered = [t for t in out if (status is None or t["status"] == status)
                and (status_not is None or t["status"] != status_not) and (role is None or t["role"] == role)]
    return [_compact_row(t) for t in filtered] if compact else filtered


def events(since=0, limit=200, role=None, task_ids=None):
    """Events in sequence order, optionally filtered without changing their cursor."""
    rows = db().execute("select seq,task_id,ts,kind,data from events where seq>? order by seq limit ?",
                        (since, limit)).fetchall()
    page = [{"seq": s, "task": t, "ts": ts, "kind": k, "data": json.loads(d)}
            for s, t, ts, k, d in rows]
    if role is None and task_ids is None:
        return page
    return _filter_events(page, role, task_ids)


def _filter_events(page, role=None, task_ids=None):
    """Filter an already bounded page using the current task index, preserving seq."""
    ids = set(task_ids) if task_ids is not None else None
    roles = dict(db().execute("select id,role from tasks").fetchall()) if role is not None else {}
    return [event for event in page
            if (role is None or roles.get(event["task"]) == role)
            and (ids is None or event["task"] in ids)]


def normalize_usage(provider, usage):
    """Return provider-independent token buckets.

    Codex includes cached input in input_tokens. Its output_tokens is assumed to
    already include reasoning, so reasoning_output_tokens is informational and
    is deliberately not added to total_tokens a second time.
    """
    usage = usage or {}
    if provider == "codex":
        cache_read = usage.get("cached_input_tokens", 0) or 0
        input_uncached = max(0, (usage.get("input_tokens", 0) or 0) - cache_read)
        cache_write = 0
        reasoning = usage.get("reasoning_output_tokens", 0) or 0
    else:
        input_uncached = usage.get("input_tokens", 0) or 0
        cache_read = usage.get("cache_read_input_tokens", 0) or 0
        cache_write = usage.get("cache_creation_input_tokens", 0) or 0
        reasoning = usage.get("reasoning_tokens", usage.get("reasoning_output_tokens", 0)) or 0
    output = usage.get("output_tokens", 0) or 0
    return {
        "input_uncached_tokens": input_uncached, "cache_read_tokens": cache_read,
        "cache_write_tokens": cache_write, "output_tokens": output, "reasoning_tokens": reasoning,
        "total_tokens": input_uncached + cache_read + cache_write + output,
    }


_policy_cache = None
_policy_lock = threading.Lock()


def policy_version():
    """Hash policy bytes once, invalidating when policy paths or mtimes change."""
    global _policy_cache
    with _policy_lock:
        pool = STATE / "pool.toml"
        paths = [pool, *sorted((STATE / "prompts").glob("*.md"))]
        try:
            signature = tuple((path, path.stat().st_mtime_ns) for path in paths)
            if _policy_cache is None or _policy_cache[0] != signature:
                digest = hashlib.sha256()
                for path in paths:
                    digest.update(path.read_bytes())
                _policy_cache = signature, digest.hexdigest()[:12]
        except OSError:
            return None
        return _policy_cache[1]


