"""Structured, bounded evidence for orchestrator decisions.

Generic mappings: model_routing~routing, scheduling~wave/jev_sched,
workflow_strategy~strategy, and planner_routing~planner_route. Legacy call sites
keep their kinds; new context-program code uses the generic kinds.
"""

import time
from contextlib import contextmanager
from datetime import datetime
from pathlib import Path
from zoneinfo import ZoneInfo

from . import schedlog


CONTEXT_KINDS = (
    "context_selection",
    "evidence_reuse",
    "retrieval",
    "tool_disclosure",
    "instruction_loading",
    "model_routing",
    "planner_routing",
    "scheduling",
    "action_gate",
    "workflow_strategy",
    "handoff",
)

KINDS = (
    "routing",
    "wave",
    "capacity",
    "concurrency",
    "merge_pressure",
    "stale",
    "jev_sched",
    "allocation",
    "strategy",
    "speculation",
    "scout",
    "review_plan",
    "planner_route",
) + CONTEXT_KINDS

_MAX_TEXT = 2000
_TRUNCATION_MARKER = "...[truncated]"


class ExplainRows(list):
    """A list of explanations carrying the count of malformed input lines."""

    def __init__(self, rows=(), malformed_count=0):
        super().__init__(rows)
        self.malformed_count = malformed_count

    @property
    def malformed(self):
        return self.malformed_count


def _bounded(value):
    if isinstance(value, str):
        if len(value) > _MAX_TEXT:
            return value[: _MAX_TEXT - len(_TRUNCATION_MARKER)] + _TRUNCATION_MARKER
        return value
    if isinstance(value, list):
        return [_bounded(item) for item in value]
    if isinstance(value, tuple):
        return [_bounded(item) for item in value]
    if isinstance(value, dict):
        return {_bounded(key): _bounded(item) for key, item in value.items()}
    return value


def _directory(root=None):
    if root is None:
        return schedlog.SCHED_DIR
    root = Path(root)
    return root / "runs" / "sched"


@contextmanager
def _using_root(root):
    if root is None:
        yield
        return
    original = schedlog.SCHED_DIR
    schedlog.SCHED_DIR = _directory(root)
    try:
        yield
    finally:
        schedlog.SCHED_DIR = original


def _append(row, root=None):
    row = dict(row)
    row.setdefault("ts", time.time())
    with _using_root(root):
        schedlog.append("decisions", row)
    return row


def record(
    kind,
    subject,
    *,
    candidates,
    hard_constraints,
    deterministic,
    historical=None,
    jev=None,
    selected,
    rejected=None,
    reason,
    confidence=None,
    n=None,
    mode=None,
    extra=None,
    root=None,
):
    """Append one bounded decision evidence row and return it."""
    if kind not in KINDS:
        raise ValueError(f"invalid decision kind: {kind}")

    if rejected is None:
        selected_values = selected if isinstance(selected, (list, tuple, set)) else [selected]
        rejected = [candidate for candidate in candidates if candidate not in selected_values]

    row = {
        "kind": kind,
        "subject": subject,
        "candidates": candidates,
        "hard_constraints": hard_constraints,
        "deterministic": deterministic,
        "historical": historical,
        "jev": jev,
        "selected": selected,
        "rejected": rejected,
        "reason": reason,
        "confidence": confidence,
        "n": n,
        "mode": mode,
        "extra": extra,
    }
    return _append(_bounded(row), root=root)


def outcome(subject, kind, root=None, **fields):
    """Append an outcome linked to a prior decision kind."""
    row = {
        "kind": "outcome",
        "subject": subject,
        "decision_kind": kind,
        **fields,
    }
    return _append(_bounded(row), root=root)


def _read(root=None):
    with _using_root(root):
        return schedlog.read_with_malformed("decisions")


def read_all(root=None, since_ts=None):
    rows, _malformed = _read(root)
    if since_ts is None:
        return rows
    return [row for row in rows if row.get("ts", 0) >= since_ts]


def explain(subject, kinds=None, root=None):
    """Return decisions newest first, assigning outcomes to the latest predecessor."""
    rows, malformed = _read(root)
    wanted = set(kinds) if kinds is not None else None
    decisions = []
    latest = {}
    # Stable ordering preserves append order when timestamps tie.
    for row in sorted(rows, key=[REDACTED] row: row.get("ts", 0)):
        if row.get("subject") != subject:
            continue
        if row.get("kind") == "outcome":
            decision = latest.get(row.get("decision_kind"))
            if decision is not None:
                decision["outcomes"].append(dict(row))
            continue
        if wanted is not None and row.get("kind") not in wanted:
            continue
        decision = dict(row)
        decision["outcomes"] = []
        latest[row.get("kind")] = decision
        decisions.append(decision)
    decisions.sort(key=[REDACTED] row: row.get("ts", 0), reverse=True)
    return ExplainRows(decisions, malformed)


def _timestamp(value):
    try:
        return datetime.fromtimestamp(float(value), ZoneInfo("Europe/Zurich")).isoformat()
    except (TypeError, ValueError, OSError, OverflowError):
        return str(value)


def _rejected_summary(rejected):
    if isinstance(rejected, dict):
        return ", ".join(f"{item}: {why}" for item, why in rejected.items())
    if isinstance(rejected, (list, tuple, set)):
        return ", ".join(map(str, rejected))
    return str(rejected) if rejected is not None else "none"


def format_explain(rows):
    """Format explanation rows as concise, human-readable evidence lines."""
    lines = []
    for row in rows:
        lines.append(f"{_timestamp(row.get('ts'))} {row.get('kind')} subject={row.get('subject')}")
        lines.append(f"selected: {row.get('selected')}")
        lines.append(f"reason: {row.get('reason')}")
        lines.append(f"rejected: {_rejected_summary(row.get('rejected'))}")
        confidence = row.get("confidence")
        n = row.get("n")
        if confidence is not None or n is not None:
            lines.append(f"confidence/n: {confidence}/{n}")
        outcomes = row.get("outcomes", ())
        if outcomes:
            summary = "; ".join(
                ", ".join(f"{key}={value}" for key, value in outcome.items() if key not in {"ts", "kind", "subject", "decision_kind"})
                for outcome in outcomes
            )
            lines.append(f"outcome: {summary}")
    return "\n".join(lines)

"""Context-economy reporting from run-log packet telemetry."""
import json
from collections import defaultdict
from pathlib import Path

from . import STATE, attribution


def _entries(root):
    for path in sorted((Path(root) / "runs").glob("*.jsonl")):
        for line in path.read_text().splitlines():
            try:
                yield json.loads(line)
            except json.JSONDecodeError:
                continue


def _avg(values):
    return round(sum(values) / len(values), 2) if values else None


def _shadow(rows):
    contexts = [row["context"] for row in rows if isinstance(row.get("context"), dict)]
    measured = [context for context in contexts if context.get("routed_tokens") is not None]
    candidates = [len(context.get("evidence_ids") or []) for context in measured]
    return {
        "shadow_routed_tokens": _avg([context["routed_tokens"] for context in measured]),
        "shadow_reduction": _avg([context["routed_reduction_ratio"] for context in measured
                                  if context.get("routed_reduction_ratio") is not None]),
        "shadow_hidden": _avg([context["routed_hidden"] for context in measured
                               if context.get("routed_hidden") is not None]),
        "shadow_ambiguous_rate": _avg([
            context.get("routed_ambiguous", 0) / count for context, count in zip(measured, candidates) if count]),
        "shadow_unmeasured": len(rows) - len(measured),
    }


def build(root=STATE):
    entries = list(_entries(root))
    tasks = {}
    for path in sorted((Path(root) / "tasks").glob("*.json")):
        try:
            task = json.loads(path.read_text())
            tasks[task.get("id", path.stem)] = task
        except (OSError, ValueError, TypeError):
            continue
    roles = {}
    for role in sorted({row.get("role") or "?" for row in entries}):
        rows = [row for row in entries if (row.get("role") or "?") == role]
        measured = [row for row in rows if isinstance(row.get("context"), dict)]
        presented = [row["context"].get("presented_tokens") for row in measured
                     if row["context"].get("presented_tokens") is not None]
        candidate_rows = [row for row in measured if row["context"].get("candidate_known")
                          and row["context"].get("candidate_tokens") is not None]
        candidate = [row["context"]["candidate_tokens"] for row in candidate_rows]
        candidate_presented = [row["context"].get("presented_tokens", 0) for row in candidate_rows]
        instructions = [row["context"].get("instruction_tokens") for row in measured
                        if row["context"].get("instruction_tokens") is not None]
        modular_rows = [row for row in measured
                        if row["context"].get("instruction_tokens_modular") is not None]
        modular = [row["context"]["instruction_tokens_modular"] for row in modular_rows]
        modular_legacy = [row["context"].get("instruction_tokens") for row in modular_rows]
        disclosed = [row["context"].get("tool_tokens_disclosed") for row in measured
                     if row["context"].get("tool_tokens_disclosed") is not None]
        minimal = [row["context"].get("tool_tokens_minimal") for row in measured
                   if row["context"].get("tool_tokens_minimal") is not None]
        sections = defaultdict(list)
        for row in measured:
            for name, meta in (row["context"].get("sections") or {}).items():
                sections[name].append(meta.get("est_tokens", 0))
        roles[role] = {"runs": len(rows), "measured": len(measured),
                       "unmeasured": len(rows) - len(measured), "avg_presented": _avg(presented),
                       "avg_candidate": _avg(candidate),
                       "reduction_ratio": round(1 - sum(candidate_presented) / sum(candidate), 3)
                       if candidate and sum(candidate) else None,
                       "avg_instruction_tokens": _avg(instructions),
                       "instruction_tokens": _avg(instructions),
                       "instruction_tokens_modular": _avg(modular),
                       "instruction_reduction": round(sum(modular) / sum(modular_legacy), 3)
                       if modular_legacy and sum(modular_legacy) else None,
                       "instruction_unmeasured": len(rows) - len(modular_rows),
                       "tool_tokens_disclosed": _avg(disclosed), "tool_tokens_minimal": _avg(minimal),
                       "tool_reduction": round(sum(minimal) / sum(disclosed), 3) if disclosed and sum(disclosed) else None,
                       "top_sections": sorted(((name, _avg(values)) for name, values in sections.items()),
                                              key=[REDACTED] item: (-item[1], item[0]))[:5], **_shadow(rows)}
    goals = {}
    for goal in sorted({row.get("goal_id") for row in entries if row.get("goal_id")}):
        rows = [row for row in entries if row.get("goal_id") == goal]
        measured = [row for row in rows if isinstance(row.get("context"), dict)]
        total = unique = 0
        by_section = {}
        occurrences = defaultdict(list)
        for row in measured:
            for name, meta in (row["context"].get("sections") or {}).items():
                token_count=[REDACTED] 0)
                total += token_count
                occurrences[name].append((meta.get("sha256"), token_count, row.get("role")))
        for name, values in occurrences.items():
            unique_tokens=[REDACTED] for digest2, tokens, _ in values if digest2 == digest)
                                for digest in {digest for digest, _, _ in values})
            by_section[name] = round(sum(tokens for _, tokens, _ in values) / unique_tokens, 3) if unique_tokens else 0.0
            unique += unique_tokens
        repeated = sorted(name for name, values in occurrences.items()
                          if any(len({role for digest2, _, role in values if digest2 == digest}) >= 2
                                 for digest in {digest for digest, _, _ in values}))
        goals[goal] = {"runs": len(rows), "measured": len(measured),
                       "amplification": round(total / unique, 3) if unique else None,
                       "amplification_by_section": by_section, "repeated_sections": repeated,
                       "lineage_roots": sorted({row.get("lineage_root") for row in rows if row.get("lineage_root")}),
                       **_shadow(rows)}
    by_role_class = {}
    for key in sorted({(row.get("role") or "unknown",
                        attribution.task_class(tasks[row.get("task")]) if row.get("task") in tasks else "unknown")
                       for row in entries}):
        selected = [row for row in entries if (row.get("role") or "unknown") == key[0] and
                    (attribution.task_class(tasks[row.get("task")]) if row.get("task") in tasks else "unknown") == key[1]]
        contexts = [row["context"] for row in selected if isinstance(row.get("context"), dict)]
        disclosed = [c["tool_tokens_disclosed"] for c in contexts if c.get("tool_tokens_disclosed") is not None]
        minimal = [c["tool_tokens_minimal"] for c in contexts if c.get("tool_tokens_minimal") is not None]
        by_role_class[key] = {"runs": len(selected), "measured": len(contexts),
                              "tool_tokens_disclosed": _avg(disclosed), "tool_tokens_minimal": _avg(minimal),
                              "tool_reduction": round(sum(minimal) / sum(disclosed), 3) if disclosed and sum(disclosed) else None,
                              **_shadow(selected)}
    return {"roles": roles, "goals": goals, "by_role_task_class": by_role_class}


