from __future__ import annotations

import base64
import difflib
import hashlib
import json
import re
import subprocess
import tomllib
from dataclasses import asdict
from pathlib import Path, PurePosixPath
from urllib.parse import quote, urlparse

from . import STATE
from . import skills_registry as registry

MAX_FILES = 50
MAX_BYTES = 200 * 1024
SEARCH_ROOTS = ("skills", ".claude/skills", ".codex/skills")


def _config(root):
    try:
        return tomllib.loads((Path(root) / "pool.toml").read_text()).get("skills", {})
    except (OSError, ValueError):
        return {}


def _git(path, *args):
    result = subprocess.run(["git", "-C", str(path), *args], capture_output=True,
                            text=True, timeout=30, check=False)
    return result.stdout.strip() if result.returncode == 0 else ""


def _repo_name(remote):
    match = re.search(r"(?:github\.com[:/])([^/]+/[^/]+?)(?:\.git)?/?$", remote)
    return match.group(1) if match else remote.removesuffix(".git").strip("/")


def _gh_api(endpoint):
    result = subprocess.run(["gh", "api", endpoint], capture_output=True, text=True,
                            timeout=30, check=False)
    if result.returncode:
        raise ValueError("GitHub retrieval failed: " + result.stderr.strip()[:300])
    return json.loads(result.stdout)


def _safe_path(value):
    path = PurePosixPath(value)
    if path.is_absolute() or not path.parts or any(p in ("..", ".") for p in path.parts):
        raise ValueError("unsafe source path")
    return path


def _hash(files):
    digest = hashlib.sha256()
    for name, data in sorted(files.items()):
        digest.update(name.encode() + b"\0" + data + b"\0")
    return digest.hexdigest()[:12]


def _bounded(files, name, data):
    _safe_path(name)
    if name == "findings.json":
        raise ValueError("reserved quarantine report filename")
    if len(files) >= MAX_FILES or sum(map(len, files.values())) + len(data) > MAX_BYTES:
        raise ValueError("skill exceeds 50 files or 200 KB cap")
    files[name] = data


def _local_files(directory):
    files = {}
    for path in sorted(directory.rglob("*")):
        if path.is_symlink():
            raise ValueError("symlinks are refused")
        if path.is_file():
            if path.stat().st_size > MAX_BYTES:
                raise ValueError("skill exceeds 200 KB cap")
            _bounded(files, path.relative_to(directory).as_posix(), path.read_bytes())
    return files


def _remote_files(repo, commit, directory):
    files = {}
    directories = 0

    def walk(path):
        nonlocal directories
        directories += 1
        if directories > MAX_FILES:
            raise ValueError("skill exceeds directory cap")
        entries = _gh_api(f"repos/{repo}/contents/{quote(path, safe='/')}?ref={quote(commit, safe='')}")
        if not isinstance(entries, list):
            raise ValueError("expected GitHub directory")
        for item in sorted(entries, key=[REDACTED] row: row["path"]):
            name = str(_safe_path(item["path"]).relative_to(directory))
            if item["path"] != str(PurePosixPath(path) / item["name"]):
                raise ValueError("unexpected GitHub path")
            if item["type"] == "dir":
                walk(item["path"])
            elif item["type"] == "file":
                if len(files) >= MAX_FILES or item.get("size", 0) + sum(map(len, files.values())) > MAX_BYTES:
                    raise ValueError("skill exceeds 50 files or 200 KB cap")
                content = _gh_api(f"repos/{repo}/contents/{quote(item['path'], safe='/')}?ref={quote(commit, safe='')}")
                if content.get("type") != "file" or content.get("encoding") != "base64":
                    raise ValueError("unsupported GitHub file")
                _bounded(files, name, base64.b64decode(content["content"]))
            else:
                raise ValueError("symlinks and submodules are refused")
    walk(directory)
    return files


def _fetch(source, root):
    """Return candidates plus per-source errors, without invoking source code."""
    candidates, errors = [], []
    local = Path(source).expanduser()
    try:
        if local.exists():
            local = local.resolve()
            builtin = (registry.REPO / "skills").resolve()
            if local == builtin or local.is_relative_to(builtin):
                raise ValueError("builtin path refused: already registered")
            repo = _repo_name(_git(local, "remote", "get-url", "origin"))
            source_repo = repo or str(local)
            commit = _git(local, "rev-parse", "HEAD") or None
            trusted = repo in _config(root).get("trusted_repos", []) if repo else False
            provenance = "repository" if trusted else "external"
            bases = [local / name for name in SEARCH_ROOTS]
            if local.name == "skills" or (local / "SKILL.md").is_file():
                bases = [local]
            license_path = local / "LICENSE"
            license_text = license_path.read_text()[:MAX_BYTES] if license_path.is_file() and not license_path.is_symlink() else None
            for skill in sorted({p for base in bases for p in base.rglob("SKILL.md")}):
                try:
                    if any(p.is_symlink() for p in (skill, *skill.parents) if p.is_relative_to(local)):
                        raise ValueError("symlinks are refused")
                    if skill.resolve().is_relative_to(builtin):
                        raise ValueError("builtin path refused: already registered")
                    files = _local_files(skill.parent)
                    candidates.append((source_repo, skill.relative_to(local).as_posix(), commit,
                                       provenance, files, license_text, str(local), None,
                                       [p.relative_to(skill.parent).as_posix() for p in skill.parent.rglob("*")
                                        if p.is_file() and p.stat().st_mode & 0o111]))
                except (OSError, ValueError) as error:
                    errors.append(str(error))
        else:
            match = re.fullmatch(r"([\w.-]+/[\w.-]+)(?:@(.+))?", source)
            if not match:
                raise ValueError("expected local path or owner/repo[@ref]")
            repo, ref = match.groups()
            ref = ref or _gh_api(f"repos/{repo}")["default_branch"]
            commit = _gh_api(f"repos/{repo}/commits/{quote(ref, safe='')}")["sha"]
            license_text = None
            # Repository root listing avoids treating a missing license as a retrieval failure.
            listing = _gh_api(f"repos/{repo}/contents?ref={quote(commit, safe='')}")
            for item in listing:
                if item["name"] == "LICENSE" and item.get("type") == "file" and item.get("size", 0) <= MAX_BYTES:
                    value = _gh_api(f"repos/{repo}/contents/LICENSE?ref={quote(commit, safe='')}")
                    license_text = base64.b64decode(value["content"]).decode("utf-8", errors="replace")
            visited = 0

            def search(path):
                nonlocal visited
                visited += 1
                if visited > 500:
                    raise ValueError("repository discovery directory cap exceeded")
                entries = _gh_api(f"repos/{repo}/contents/{quote(path, safe='/')}?ref={quote(commit, safe='')}")
                if any(i["name"] == "SKILL.md" and i["type"] == "file" for i in entries):
                    try:
                        files = _remote_files(repo, commit, path)
                        candidates.append((repo, path + "/SKILL.md", commit, "external", files,
                                           license_text, repo, ref, []))
                    except (OSError, ValueError, KeyError) as error:
                        errors.append(str(error))
                    return
                for item in entries:
                    if item["type"] == "dir":
                        expected = str(PurePosixPath(path) / item["name"])
                        if str(_safe_path(item["path"])) != expected:
                            raise ValueError("unexpected GitHub path")
                        search(expected)
            for base in SEARCH_ROOTS:
                try:
                    search(base)
                except (OSError, ValueError, KeyError) as error:
                    errors.append(f"{base}: {error}")
    except (OSError, ValueError, KeyError, TypeError, subprocess.TimeoutExpired) as error:
        errors.append(str(error))
    return candidates, errors


def _store(candidate, root, *, new_version=False):
    repo, source_path, commit, provenance, files, license_text, source, ref, executable_files = candidate
    path = Path(root) / "skills" / "discovered.json"
    document = registry._read_json(path, {"version": 1, "skills": {}})
    records = document["skills"]
    now, content_hash = registry._now(), _hash(files)
    previous = next((r for r in records.values()
                     if (r.get("provenance_info") or {}).get("source_repo") == repo
                     and (r.get("provenance_info") or {}).get("source_path") == source_path), None)
    if previous and not new_version and previous["content_hash"] == content_hash:
        previous["provenance_info"]["retrieved_at"] = now
        registry._write_json(path, document)
        return previous
    name = PurePosixPath(source_path).parent.name
    repo_id = repo.replace("/", "-") if not Path(repo).is_absolute() else "local-" + hashlib.sha256(repo.encode()).hexdigest()[:12]
    skill_id = f"{provenance}/{repo_id}/{name}"
    if previous and not new_version:
        skill_id = previous["id"]
    elif new_version:
        skill_id += "@" + content_hash
    elif skill_id in registry.load(root)["skills"]:
        skill_id += "-" + hashlib.sha256(source_path.encode()).hexdigest()[:8]
    _safe_path(skill_id)
    if new_version and skill_id in records:
        return records[skill_id]
    directory = Path(root) / "skills" / "quarantine" / skill_id
    # All retained files are plain data, written without executable permissions.
    directory.mkdir(parents=True, exist_ok=True)
    for existing in directory.rglob("*"):
        if existing.is_file():
            existing.unlink()
    for filename, data in files.items():
        target = directory / str(_safe_path(filename))
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(data)
        target.chmod(0o600)
    text = files["SKILL.md"].decode("utf-8", errors="replace")
    description = re.search(r"(?m)^description:\s*(.*)$", text)
    heading = re.search(r"(?m)^#+\s+(.+)$", text)
    description = description.group(1).strip('"\'') if description else heading.group(1) if heading else ""
    info = dict(source_repo=repo, source_path=source_path, source_commit=commit, retrieved_at=now,
                license=license_text, content_hash=content_hash, modifications=[])
    record = asdict(registry.SkillRecord(
        id=skill_id, version=content_hash, content_hash=content_hash, name=name, description=description,
        provenance=provenance, trust="untrusted", state="discovered", roles=[], task_classes=[], triggers=[],
        tools=[], context_requirements=[], output_contract="", est_tokens_l0=[REDACTED] est_tokens_l1=[REDACTED]
        est_tokens_l2=[REDACTED] security_class="unknown", repo_scope="", validation={},
        promotion_state="discovered", created_at=now, updated_at=now,
        source=str(directory / "SKILL.md"), provenance_info=info))
    record.update(upstream_source=source, upstream_ref=ref, executable_files=executable_files)
    states = registry._state_document(root)
    if previous and not new_version:
        record.update(state=previous["state"], promotion_state=previous["state"], created_at=previous["created_at"])
        info["modifications"] = previous["provenance_info"]["modifications"]
    entry = states.s

"""Canonical inventory and lifecycle state for repository skills."""
from __future__ import annotations

import ast
import fnmatch
import hashlib
import json
import re
import subprocess
from dataclasses import asdict, dataclass
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

from . import STATE, attribution


REPO = Path(__file__).resolve().parents[1]
STATES = ("discovered", "quarantined", "testing", "shadow", "active", "demoted", "disabled")
ALLOWED_TRANSITIONS = {
    "discovered": {"quarantined", "testing", "disabled"},
    "quarantined": {"testing", "disabled"},
    "testing": {"shadow", "disabled", "quarantined"},
    "shadow": {"active", "testing", "disabled"},
    "active": {"demoted", "disabled", "shadow"},
    "demoted": {"shadow", "testing", "disabled"},
    "disabled": {"discovered", "testing"},
}
BASELINE_REASON = "builtin baseline 2026-09-22"


@dataclass
class SkillRecord:
    id: str
    version: str
    content_hash: str
    name: str
    description: str
    provenance: str
    trust: str
    state: str
    roles: list[str]
    task_classes: list[str]
    triggers: list[str]
    tools: list[str]
    context_requirements: list[str]
    output_contract: str
    est_tokens_l0: int
    est_tokens_l1: int
    est_tokens_l2: int
    security_class: str
    repo_scope: str
    validation: dict[str, Any]
    promotion_state: str
    created_at: str
    updated_at: str
    source: str
    provenance_info: dict[str, Any] | None = None


def _now() -> str:
    return datetime.now(timezone.utc).isoformat()


def _paths(root: Path) -> tuple[Path, Path]:
    directory = Path(root) / "skills"
    return directory / "registry.json", directory / "state.json"


def _read_json(path: Path, default: Any) -> Any:
    try:
        return json.loads(path.read_text())
    except (OSError, ValueError):
        return default


def _write_json(path: Path, value: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value, indent=2, sort_keys=[REDACTED] + "\n")


def _scalar(value: str) -> Any:
    value = value.strip()
    if not value:
        return ""
    if value.startswith("["):
        try:
            parsed = ast.literal_eval(value)
            return parsed if isinstance(parsed, list) else value
        except (ValueError, SyntaxError):
            return [part.strip().strip("'\"") for part in value[1:-1].split(",") if part.strip()]
    return value.strip("'\"")


def _frontmatter(text: str) -> tuple[dict[str, Any], str]:
    if not text.startswith("---\n"):
        return {}, text
    end = text.find("\n---\n", 4)
    if end < 0:
        return {}, text
    data: dict[str, Any] = {}
    current = None
    for line in text[4:end].splitlines():
        item = re.match(r"^\s*-\s+(.+)$", line)
        if item and current:
            if not isinstance(data[current], list):
                data[current] = []
            data[current].append(_scalar(item.group(1)))
            continue
        match = re.match(r"^([A-Za-z0-9_-]+):\s*(.*)$", line)
        if match:
            current = match.group(1)
            data[current] = _scalar(match.group(2))
    return data, text[end + 5:]


def _list(value: Any, default: list[str] | None = None) -> list[str]:
    if value in (None, ""):
        return list(default or [])
    if isinstance(value, list):
        return [str(item) for item in value]
    return [str(value)]


def _content_hash(skill_dir: Path, skill_file: Path) -> str:
    digest = hashlib.sha256()
    digest.update(skill_file.read_bytes())
    for folder in ("scripts", "references"):
        base = skill_dir / folder
        if base.exists():
            for path in sorted(item for item in base.rglob("*") if item.is_file()):
                digest.update(path.relative_to(skill_dir).as_posix().encode())
                digest.update(b"\0")
                digest.update(path.read_bytes())
    return digest.hexdigest()[:12]


def _triggers(description: str) -> list[str]:
    match = re.search(r"\bUse (?:when|for)\s+(.+?)(?:[.;]|$)", description, re.I)
    if not match:
        return []
    words = re.findall(r"[a-z0-9][a-z0-9_-]+", match.group(1).lower())
    return list(dict.fromkeys(word for word in words if len(word) >= 4))


def _output_contract(meta: dict[str, Any], body: str) -> str:
    if meta.get("output"):
        value = meta["output"]
        return (", ".join(value) if isinstance(value, list) else str(value))[:300]
    match = re.search(r"(?:Finish with|\bOutput\b)\s*:?[ \t]*(.+)", body, re.I)
    return re.sub(r"\s+", " ", match.group(1)).strip()[:300] if match else ""


def _token_estimate(text: str) -> int:
    """Estimate the disclosed procedural payload; metadata sections are indexed separately."""
    sections = _sections(text)
    if sections:
        text = "\n".join(sections[name].split("\n", 1)[-1]
                         for name in ("Procedure", "Output contract"))
    return len(text) // 4


def _git_dates(path: Path) -> tuple[str, str]:
    try:
        result = subprocess.run(
            ["git", "log", "--follow", "--format=%aI", "--", str(path)], cwd=REPO,
            capture_output=True, text=True, check=False,
        )
        dates = [line for line in result.stdout.splitlines() if line]
        if dates:
            return dates[-1], dates[0]
    except OSError:
        pass
    stamp = datetime.fromtimestamp(path.stat().st_mtime, timezone.utc).isoformat()
    return stamp, stamp


def _roles(role: str, explicit: Any) -> list[str]:
    if explicit not in (None, ""):
        return _list(explicit)
    return [role, "spec_review", "challenge"] if role == "review" else [role]


def _tests_for(skill_dir: Path, tests_dir: Path) -> list[str]:
    needle = skill_dir.relative_to(skill_dir.parents[2]).as_posix()
    found = []
    if tests_dir.exists():
        for test in sorted(tests_dir.glob("test_*.py")):
            try:
                if needle in test.read_text():
                    found.append(test.relative_to(tests_dir.parent).as_posix())
            except (OSError, UnicodeDecodeError):
                pass
    return found


def _state_document(root: Path) -> dict[str, Any]:
    _, state_path = _paths(root)
    value = _read_json(state_path, {})
    return value if isinstance(value, dict) else {}


def state(skill_id: str, root: Path = STATE) -> dict[str, Any]:
    """Return explicit lifecycle state; provenance is deliberately not consulted."""
    entry = _state_document(Path(root)).get(skill_id)
    if not entry:
        raise KeyError(skill_id)
    return entry


def sync(root: Path = STATE, skills_dir: Path = REPO / "skills") -> dict[str, Any]:
    root, skills_dir = Path(root), Path(skills_dir)
    registry_path, state_path = _paths(root)
    old_registry = _read_json(registry_path, {"skills": {}})
    old_records = old_registry.get("skills", {}) if isinstance(old_registry, dict) else {}
    states = _state_document(root)
    records: dict[str, dict[str, Any]] = {}
    now = _now()

    for skill_file in sorted(skills_dir.glob("*/*/SKILL.md")):
        role, directory_name = skill_file.parent.parent.name, skill_file.parent.name
        skill_id = f"{role}/{directory_name}"
        text = skill_file.read_text()
        meta, body = _frontmatter(text)
        version = _content_hash(skill_file.parent, skill_file)
        entry = states.get(skill_id)
        if entry is None:
            entry = {"state": "active", "trust": "trusted", "since": now,
                     "reason": BASELINE_REASON, "history": []}
            states[skill_id] = entry
        previous = old_records.get(skill_id, {})
        old_version = previous.get("version")
        if old_version and old_version != version:
            history = entry.setdefault("history", [])
            history.append({"at": now, "from": entry["state"], "to": entry["state"],
                            "reason": f"content changed: {old_version}→{version}"})
            entry["since"] = now
            entry["reason"] = history[-1]["reason"]
            if entry.get("trust") != "trusted":
                entry["state"] = "testing"
        scripts = sorted(
            "script:" + path.relative_to(skill_file.parent).as_posix()
            for path in (skill_file.parent / "scripts").rglob("*")
            if path.is_file()
        ) if (skill_file.parent / "scripts").exists() else []
        tools = _list(meta.get("allowed-tools", meta.get("tools"))) + scripts
        triggers = _list(meta.get("triggers")) or _triggers(str(meta.get("description", "")))
        objective = re.sub(r"^#+\s+", "", body.strip().splitlines()[0]) if body.strip() else ""
        output = _output_contract(meta, body)
        tests = _tests_for(skill_file.parent, REPO / "tests")
        created, updated = _git_dates(skill_file)
        record = SkillRecord(
            id=skill_id, version=version, content_hash=version,
            name=str(meta.get("name", directory_name)), description=str(meta.get("description", "")),
            provenance="builtin", trust=entry["trust"], state=entry["state"],
            roles=_roles(role, meta.get("roles")), task_classes=_list(meta.get("task_classes"), ["*"]),
            triggers=triggers, tools=list(dict.fromkeys(tools)),
            context_requirements=_list(meta.get("requires_context")), output_contract=output,
            est_tokens_l0=[REDACTED] ""))) // 4,
            est_tokens_l1=[REDACTED] ".join(triggers + ([objective] if objective else []) + ([output] if output else []))) // 4,
            est_tokens_l2=[REDACTED] security_class=str(meta.get("security", "internal")),
            repo_scope=str(meta.get("repo", "orchestrator")),
            validation={"tests": tests, "status": "tested" if tests else "untested"},
            promotion_state=entry["state"], created_at=created, updated_at=updated,
            source=skill_file.relative_to(REPO).as_posix() if skill_file.is_relative_to(REPO) else str(skill_file),
        )
        records[skill_id] = asdict(record)

    for skill_id, previous in old_records.items():
        if previous.get("provenance") != "builtin":
            records[skill_id] = previous
            continue
        if skill_id in records:
            continue
        entry = states.setdefault(skill_id, {"state": previous.get("state", "discovered"),
                                             "trust": previous.get("trust", "untrusted"),
                                             "since": now, "reason": "", "history": []})
        if entry.get("state") != "disabled" or entry.get("reason") != "source removed":
            entry.setdefault("history", []).append({"at": now, "from": entry.get("state"),
                                                    "to": "disabled", "reason": "source removed"})
            entry.update({"state": "disabled", "since": now, "reason": "source removed"})
        missing = dict(previous)
        missing.update(state="disabled", promotion_state="disabled", trust=entry["trust"])
        records[skill_id] = missing

    document = {"version": 1, "synced_at": now, "skills": records}
    _write_json(state_path, states)
    _write_json(registry_path, document)
    return document


