"""Read-only, version-windowed lifecycle recommendations. The CLI applies them."""
from __future__ import annotations

import json
import time
from pathlib import Path

from . import STATE, decision_log, skill_scorecard, skills_registry as registry


def version_window(record, entry, now=None):
    now = time.time() if now is None else now
    versions = list(entry.get("versions") or record.get("versions") or [])
    versions += [{"content_hash": row.get("version"), "at": row.get("at")}
                 for row in entry.get("history", []) if row.get("version")]
    # Older registry history recorded the hash in the reason rather than a field.
    versions += [{"content_hash": row["reason"].split("→")[-1], "at": row.get("at")}
                 for row in entry.get("history", [])
                 if str(row.get("reason", "")).startswith("content changed:") and "→" in row["reason"]]
    starts = [skill_scorecard.timestamp(v.get("at")) for v in versions
              if v.get("content_hash") == record["version"]]
    starts = [stamp for stamp in starts if stamp is not None]
    start = max(starts) if starts else skill_scorecard.timestamp(record.get("updated_at"))
    # Missing provenance cannot borrow old evidence.
    return (now if start is None else start), now


def suite_ready(root, now=None):
    now = time.time() if now is None else now
    report = registry._read_json(Path(root) / "skill_eval.json", {})
    stamp = skill_scorecard.timestamp(report.get("ran_at"))
    return bool(report.get("suite_passed") is True and stamp is not None and 0 <= now - stamp <= 7 * 86400)


def _inspection(record, root):
    report = registry._read_json(Path(root) / "skills/quarantine" / record["id"] / "findings.json", {})
    if record.get("provenance") != "builtin":
        if not report or report.get("content_hash") != record.get("content_hash"):
            return False, False
        from .skill_discovery import _hash
        directory = Path(root) / "skills/quarantine" / record["id"]
        files = {}
        for path in directory.rglob("*"):
            if path.is_symlink():
                return False, False
            if path.is_file() and path != directory / "findings.json":
                files[path.relative_to(directory).as_posix()] = path.read_bytes()
        if _hash(files) != record.get("content_hash"):
            return False, False
    return report.get("max_severity") != "block", not bool(report.get("findings"))


def _irrelevant(skill_id, root, since, until, usage):
    logs = [r for r in decision_log.read_all(root=root) if skill_scorecard.in_window(r, since, until)]
    outcomes = {r.get("subject"): r for r in logs
                if r.get("kind") == "outcome" and r.get("decision_kind") == "skill_selection"}
    used_by_task = {r.get("task"): r["skills_used"] for r in usage}
    selected = unused = 0
    for row in logs:
        if row.get("kind") != "skill_selection" or skill_id not in (row.get("selected") or []):
            continue
        used = outcomes.get(row.get("subject"), {}).get("skills_used", used_by_task.get(row.get("subject")))
        if used is None:  # Pending spawns are not evidence of non-use.
            continue
        selected += 1
        unused += skill_id not in used
    return {"selected": selected, "unused": unused,
            "rate": unused / selected if selected else None}


def _newer_conflict(skill_id, records, root, since, until):
    current = registry.state(skill_id, root)
    for row in decision_log.read_all(root=root):
        if row.get("kind") != "skill_selection" or not skill_scorecard.in_window(row, since, until):
            continue
        specialist = (row.get("extra") or {}).get("specialist") or (row.get("deterministic") or {}).get("specialist") or {}
        for conflict in specialist.get("conflicts", []):
            pair = {conflict.get("kept"), conflict.get("dropped")}
            if skill_id not in pair:
                continue
            for other in pair - {skill_id}:
                if records.get(other, {}).get("state") == "active":
                    other_entry = registry.state(other, root)
                    if (skill_scorecard.timestamp(other_entry.get("since")) or 0) > (skill_scorecard.timestamp(current.get("since")) or 0):
                        return conflict
    return None


def evaluate_skill(skill_id, root=STATE, cfg=None):
    """Recommend one transition without mutating state or running validation tests."""
    root = Path(root)
    cfg = cfg or {}
    minimum = max(20, int(cfg.get("promotion", {}).get("min_samples", 20)))
    records = registry.load(root)["skills"]
    record, entry = records[skill_id], registry.state(skill_id, root)
    since, until = version_window(record, entry)
    marginal = skill_scorecard.marginal(root, skill_id, min_samples=minimum, since_s=since, until_s=until)
    usage = skill_scorecard.usage_rows(root, since_s=since, until_s=until)
    irrelevant = _irrelevant(skill_id, root, since, until, usage)
    evidence = {"version": record["version"], "since_s": since, "until_s": until,
                "min_samples": minimum, "marginal": marginal, "irrelevant": irrelevant}
    status = entry["state"]
    target = None
    why = "insufficient evidence"
    inspected, secure = _inspection(record, root)
    validation = record.get("validation") or {}
    tested = validation.get("status") == "tested" and validation.get("version", record["version"]) == record["version"]
    sufficient = [r for r in marginal if not r.get("insufficient") and
                  min(r.get("n_with", 0), r.get("n_without", 0)) >= minimum]
    bad = [r for r in sufficient if r.get("verdict") in ("harmful", "costly")]
    efficient = any(r.get("verdict") in ("valuable", "neutral") and
                    any(r.get(key) is not None and r[key] < 0 for key in
                        ("accepted_tokens_delta", "accepted_usd_delta", "fix_rounds_delta")) for r in sufficient)
    if status == "active":
        stale_since = skill_scorecard.timestamp(record.get("stale_since"))
        stale_due = record.get("stale") and (validation.get("status") == "failed" or
                    (stale_since is not None and until - stale_since > 86400))
        conflict = _newer_conflict(skill_id, records, root, since, until)
        if stale_due:
            target, why = "shadow", "stale dependencies: validation failed or overdue"
        elif bad or (irrelevant["selected"] >= 20 and irrelevant["rate"] >= .7) or conflict:
            target, why = "demoted", "harmful/costly evidence, repeated irrelevant activation, or newer active conflict"
            evidence["conflict"] = conflict
    elif status == "testing" and tested and inspected and not record.get("stale"):
        target, why = "shadow", "validation passed and inspection below block"
    elif status == "shadow":
        if tested and inspected and secure and efficient and not bad and not record.get("stale"):
            if suite_ready(root, until):
                target, why = "active", "sufficient version evidence with measurable efficiency gain and recent passing suite"
            else:
                why = "active promotion requires a passing skill-eval within seven days"
    elif status == "demoted":
        demotions = [r for r in entry.get("history", []) if r.get("to") == "demoted" and r.get("from") != "demoted"]
        last = skill_scorecard.timestamp(demotions[-1].get("at")) if demotions else None
        if last is not None and since > last and tested and inspected and secure and efficient and not bad and not record.get("stale"):
            target, why = "shadow", "later version evidence clears demotion"
    return {"id": skill_id, "from": status, "to": target, "evidence": evidence,
            "reason": why + ": " + json.dumps(evidence, sort_keys=[REDACTED]


def recommendations(root=STATE, cfg=None):
    return [evaluate_skill(skill_id, root, cfg) for skill_id in sorted(registry.load(root)["skills"])]

"""Canonical inventory and lifecycle state for repository skills."""
from __future__ import annotations

import ast
import fnmatch
import hashlib
import json
import re
import subprocess
import sys
from dataclasses import asdict, dataclass, field
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

from . import STATE, attribution


REPO = Path(__file__).resolve().parents[1]
STATES = ("discovered", "quarantined", "testing", "shadow", "active", "demoted", "disabled")
ALLOWED_TRANSITIONS = {
    "discovered": {"quarantined", "testing", "disabled"},
    "quarantined": {"testing", "disabled"},
    "testing": {"shadow", "disabled", "quarantined"},
    "shadow": {"active", "testing", "disabled"},
    "active": {"demoted", "disabled", "shadow"},
    "demoted": {"shadow", "testing", "disabled"},
    "disabled": {"discovered", "testing"},
}
BASELINE_REASON = "builtin baseline 2026-09-22"


@dataclass
class SkillRecord:
    id: str
    version: str
    content_hash: str
    name: str
    description: str
    provenance: str
    trust: str
    state: str
    roles: list[str]
    task_classes: list[str]
    triggers: list[str]
    tools: list[str]
    context_requirements: list[str]
    output_contract: str
    est_tokens_l0: int
    est_tokens_l1: int
    est_tokens_l2: int
    security_class: str
    repo_scope: str
    validation: dict[str, Any]
    promotion_state: str
    created_at: str
    updated_at: str
    source: str
    provenance_info: dict[str, Any] | None = None
    conflicts_with: list[str] = field(default_factory=list)
    depends_on: list[str] = field(default_factory=list)
    dependency_hashes: dict[str, str] = field(default_factory=dict)
    stale: bool = False
    stale_since: str | None = None


def _now() -> str:
    return datetime.now(timezone.utc).isoformat()


def _paths(root: Path) -> tuple[Path, Path]:
    directory = Path(root) / "skills"
    return directory / "registry.json", directory / "state.json"


def _read_json(path: Path, default: Any) -> Any:
    try:
        return json.loads(path.read_text())
    except (OSError, ValueError):
        return default


def _write_json(path: Path, value: Any) -> None:
    if path.name == "discovered.json":
        _redact_drafts(value, path.parent / "quarantine")
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value, indent=2, sort_keys=[REDACTED] + "\n")


def _scalar(value: str) -> Any:
    value = value.strip()
    if not value:
        return ""
    if value.startswith("["):
        try:
            parsed = ast.literal_eval(value)
            return parsed if isinstance(parsed, list) else value
        except (ValueError, SyntaxError):
            return [part.strip().strip("'\"") for part in value[1:-1].split(",") if part.strip()]
    return value.strip("'\"")


def _frontmatter(text: str) -> tuple[dict[str, Any], str]:
    if not text.startswith("---\n"):
        return {}, text
    end = text.find("\n---\n", 4)
    if end < 0:
        return {}, text
    data: dict[str, Any] = {}
    current = None
    for line in text[4:end].splitlines():
        item = re.match(r"^\s*-\s+(.+)$", line)
        if item and current:
            if not isinstance(data[current], list):
                data[current] = []
            data[current].append(_scalar(item.group(1)))
            continue
        match = re.match(r"^([A-Za-z0-9_-]+):\s*(.*)$", line)
        if match:
            current = match.group(1)
            data[current] = _scalar(match.group(2))
    return data, text[end + 5:]


def _list(value: Any, default: list[str] | None = None) -> list[str]:
    if value in (None, ""):
        return list(default or [])
    if isinstance(value, list):
        return [str(item) for item in value]
    return [str(value)]


def _content_hash(skill_dir: Path, skill_file: Path) -> str:
    digest = hashlib.sha256()
    digest.update(skill_file.read_bytes())
    for folder in ("scripts", "references"):
        base = skill_dir / folder
        if base.exists():
            for path in sorted(item for item in base.rglob("*") if item.is_file()):
                digest.update(path.relative_to(skill_dir).as_posix().encode())
                digest.update(b"\0")
                digest.update(path.read_bytes())
    return digest.hexdigest()[:12]


def _triggers(description: str) -> list[str]:
    match = re.search(r"\bUse (?:when|for)\s+(.+?)(?:[.;]|$)", description, re.I)
    if not match:
        return []
    words = re.findall(r"[a-z0-9][a-z0-9_-]+", match.group(1).lower())
    return list(dict.fromkeys(word for word in words if len(word) >= 4))


def _output_contract(meta: dict[str, Any], body: str) -> str:
    if meta.get("output"):
        value = meta["output"]
        return (", ".join(value) if isinstance(value, list) else str(value))[:300]
    match = re.search(r"(?:Finish with|\bOutput\b)\s*:?[ \t]*(.+)", body, re.I)
    return re.sub(r"\s+", " ", match.group(1)).strip()[:300] if match else ""


def _token_estimate(text: str) -> int:
    """Estimate the disclosed procedural payload; metadata sections are indexed separately."""
    sections = _sections(text)
    if sections:
        text = "\n".join(sections[name].split("\n", 1)[-1]
                         for name in ("Procedure", "Output contract"))
    return len(text) // 4


def _git_dates(path: Path) -> tuple[str, str]:
    try:
        result = subprocess.run(
            ["git", "log", "--follow", "--format=%aI", "--", str(path)], cwd=REPO,
            capture_output=True, text=True, check=False,
        )
        dates = [line for line in result.stdout.splitlines() if line]
        if dates:
            return dates[-1], dates[0]
    except OSError:
        pass
    stamp = datetime.fromtimestamp(path.stat().st_mtime, timezone.utc).isoformat()
    return stamp, stamp


def _roles(role: str, explicit: Any) -> list[str]:
    if explicit not in (None, ""):
        return _list(explicit)
    return [role, "spec_review", "challenge"] if role == "review" else [role]


def _tests_for(skill_dir: Path, tests_dir: Path) -> list[str]:
    needle = skill_dir.relative_to(skill_dir.parents[2]).as_posix()
    found = []
    if tests_dir.exists():
        for test in sorted(tests_dir.glob("test_*.py")):
            try:
                if needle in test.read_text():
                    found.append(test.relative_to(tests_dir.parent).as_posix())
            except (OSError, UnicodeDecodeError):
                pass
    return found


def _state_document(root: Path) -> dict[str, Any]:
    _, state_path = _paths(root)
    value = _read_json(state_path, {})
    return value if isinstance(value, dict) else {}


def state(skill_id: str, root: Path = STATE) -> dict[str, Any]:
    """Return explicit lifecycle state; provenance is deliberately not consulted."""
    entry = _state_document(Path(root)).get(skill_id)
    if not entry:
        raise KeyError(skill_id)
    return entry


def sync(root: Path = STATE, skills_dir: Path = REPO / "skills") -> dict[str, Any]:
    root, skills_dir = Path(root), Path(skills_dir)
    registry_path, state_path = _paths(root)
    old_registry = _read_json(registry_path, {"skills": {}})
    old_records = old_registry.get("skills", {}) if isinstance(old_registry, dict) else {}
    states = _state_document(root)
    records: dict[str, dict[str, Any]] = {}
    now = _now()

    for skill_file in sorted(skills_dir.glob("*/*/SKILL.md")):
        role, directory_name = skill_file.parent.parent.name, skill_file.parent.name
        skill_id = f"{role}/{directory_name}"
        text = skill_file.read_text()
        meta, body = _frontmatter(text)
        version = _content_hash(skill_file.parent, skill_file)
        entry = states.get(skill_id)
        if entry is None:
            entry = {"state": "active", "trust": "trusted", "since": now,
                     "reason": BASELINE_REASON, "history": []}
            states[skill_id] = entry
        previous = old_records.get(skill_id, {})
        old_version = previous.get("version")
        versions = entry.setdefault("versions", [])
        if not versions:
            versions.append({"content_hash": old_version or version, "at": entry.get("since", now)})
        if versions[-1]["content_hash"] != version:
            versions.append({"content_hash": version, "at": now})
        if old_version and old_version != version:
            history = entry.setdefault("history", [])
            history.append({"at": now, "from": entry["state"], "to": entry["state"],
                            "reason": f"content changed: {old_version}→{version}",
                            "old_version": old_version, "version": version})
            entry["since"] = now
            entry["reason"] = history[-1]["reason"]
            if entry.get("trust") != "trusted":
                entry["state"] = "testing"
        scripts = sorted(
            "script:" + path.relative_to(skill_file.parent).as_posix()
            for path in (skill_file.parent / "scripts").rglob("*")
            if path.is_file()
        ) if (skill_file.parent / "scripts").exists() else []
        tools = _list(meta.get("allowed-tools", meta.get("tools"))) + scripts
        triggers = _list(meta.get("triggers")) or _triggers(str(meta.get("description", "")))
        objective = re.sub(r"^#+\s+", "", body.strip().splitlines()[0]) if body.strip() else ""
        output = _output_contract(meta, body)
        tests = _tests_for(skill_file.parent, REPO / "tests")
        created, updated = _git_dates(skill_file)
        dependencies = _list(meta.get("depends_on"))
        hashes = dependency_hashes(skill_file, dependencies, body, skills_dir.parent)
        changed = sorted(path for path in set(previous.get("dependency_hashes", {})) | set(hashes)
                         if previous.get("dependency_hashes", {}).get(path) != hashes.get(path)) if previous.get("dependency_hashes") is not None else []
        stale = bool(previous.get("stale") or changed)
        stale_since = previous.get("stale_since") or (now if changed else None)
        if changed:
            entry.setdefault("history", []).append({"at": now, "from": entry["state"],
                "to": entry["state"], "reason": "dependencies changed: " + ", ".join(changed),
                "changed_dependencies": changed})
        validation = dict(previous.get("validation") or {"tests": tests, "status": "untested"})
        validation["tests"] = _list(meta.get("validation_tests")) or validation.get("tests") or tests
        if changed or (old_version and old_version != version):
            validation["status"] = "untested"
        record = SkillRecord(
            id=skill_id, version=version, content_hash=version,
            conflicts_with=_list(meta.get("conflicts_with")),
            name=str(meta.get("name", directory_name)), description=str(meta.get("description", "")),
            provenance="builtin", trust=entry["trust"], state=entry["state"],
            roles=_roles(role, meta.get("roles")), task_classes=_list(meta.get("task_classes"), ["*"]),
            triggers=triggers, tools=list(dict.fromkeys(tools)),
            context_requirements=_list(meta.get("requires_context")), output_contract=output,
            est_tokens_l0=[REDACTED] ""))) // 4,
            est_tokens_l1=[REDACTED] ".join(triggers + ([objective] if objective else []) + ([output] if output else []))) // 4,
            est_tokens_l2=[REDACTED] security_class=str(meta.get("security", "internal")),
            repo_scope=str(meta.get("repo", "orchestrator")),
            validation=validation, depends_on=dependencies, dependency_hashes=hashes,
            stale=stale, stale_since=stale_since,
            promotion_state=entry["state"], created_at=created, updated_at=updated,
            source=skill_file.relative_to(REPO).as_posix() if skill_file.is_relative_to(REPO) else str(skill_file),
        )
        records[skill_id] = asdict(record)

"""Skill exposure, use, marginal-value, and redundancy reporting."""
import json
from collections import defaultdict
from itertools import combinations
from pathlib import Path

from . import STATE, attribution, decision_log, strategy


DIMENSIONS = ("role", "task_class", "band", "model", "strategy", "repo")
METRICS = ("first_pass", "fix_rounds", "gate_reds", "review_request_changes",
           "accepted", "accepted_tokens", "accepted_usd", "latency_s", "tool_calls")


def _avg(values):
    return round(sum(values) / len(values), 3) if values else None


def _json_rows(directory, pattern="*.jsonl"):
    for path in sorted(directory.glob(pattern)) if directory.exists() else []:
        for line in path.read_text(errors="replace").splitlines():
            try:
                row = json.loads(line)
            except (ValueError, TypeError):
                continue
            if isinstance(row, dict):
                yield row


def _tasks(root):
    result = {}
    for path in sorted((Path(root) / "tasks").glob("*.json")):
        try:
            row = json.loads(path.read_text())
        except (OSError, ValueError, TypeError):
            continue
        if isinstance(row, dict):
            result[row.get("id", path.stem)] = row
    return result


def _execute_root(task, tasks):
    """Resolve the execute root served by a task, using durable task-graph links."""
    current, seen = task, set()
    while isinstance(current, dict) and current.get("id") not in seen:
        seen.add(current.get("id"))
        constraints = current.get("constraints") or {}
        target = constraints.get("fix_round_for")
        if not target and current.get("role") != "execute":
            inputs = current.get("inputs") or []
            target = (constraints.get("review_for") or constraints.get("spec_review_for")
                      or (inputs[0] if inputs else None))
        if isinstance(target, str) and target in tasks:
            current = tasks[target]
            continue
        if current.get("role") == "execute":
            return strategy._root_id(current, tasks)
        break
    parent = task.get("parent") if isinstance(task, dict) else None
    candidates = [row for row in tasks.values()
                  if row.get("role") == "execute" and row.get("parent") == parent
                  and not (row.get("constraints") or {}).get("fix_round_for")]
    if len(candidates) == 1:
        return candidates[0].get("id")
    if task.get("role") in ("scout", "spec_review") and candidates:
        created = task.get("created_at")
        later = [row for row in candidates if created is None or row.get("created_at") is None
                 or row.get("created_at") >= created]
        if len(later) == 1:
            return later[0].get("id")
    return None


def _tokens(row):
    usage = row.get("usage") or {}
    values = [row.get("input_tokens", usage.get("input_tokens")),
              row.get("output_tokens", usage.get("output_tokens")),
              row.get("cache_read_input_tokens", usage.get("cache_read_input_tokens"))]
    known = [value for value in values if value is not None]
    return sum(known) if known else None


def _pool_cfg(root):
    import tomllib
    for path in (Path(root) / "pool.toml", Path(root) / ".orchestrator" / "pool.toml"):
        try:
            return tomllib.loads(path.read_text())
        except (OSError, ValueError, TypeError, tomllib.TOMLDecodeError):
            pass
    return {}


def timestamp(value):
    """Unix seconds, accepting the ISO timestamps used by older run logs."""
    from datetime import datetime, timezone
    try:
        return float(value)
    except (ValueError, TypeError):
        try:
            stamp = datetime.fromisoformat(str(value).replace("Z", "+00:00"))
            return stamp.replace(tzinfo=stamp.tzinfo or timezone.utc).timestamp()
        except (ValueError, TypeError):
            return None


def in_window(row, since_s=None, until_s=None):
    if since_s is None and until_s is None:
        return True
    stamp = timestamp(row.get("ts", row.get("at")))
    return (stamp is not None and (since_s is None or stamp >= since_s)
            and (until_s is None or stamp < until_s))


def usage_rows(root=STATE, since_s=None, until_s=None):
    """Return one outcome-attributed row for each run that records skills used."""
    root = Path(root)
    tasks = _tasks(root)
    raw = [row for row in _json_rows(root / "runs")
           if isinstance(row.get("context"), dict)
           and row["context"].get("skills_used") is not None
           and in_window(row, since_s, until_s)]
    roots = {tid: _execute_root(task, tasks) for tid, task in tasks.items()}
    root_runs = defaultdict(list)
    for row in raw:
        root_id = roots.get(row.get("task"))
        if root_id:
            root_runs[root_id].append(row)
    cfg = _pool_cfg(root)
    result = []
    for row in raw:
        task = tasks.get(row.get("task"), {})
        root_id = roots.get(row.get("task"))
        execute = tasks.get(root_id) if root_id else None
        pipeline = (execute or {}).get("pipeline") or {}
        lineage_ids = {tid for tid, rid in roots.items() if rid == root_id} if root_id else set()
        fixes = reds = None
        reviews = []
        if execute is not None:
            fixes = execute.get("lineage_fix_rounds", pipeline.get("lineage_fix_rounds"))
            if fixes is None:
                fixes = sum(tid != root_id and tasks[tid].get("role") == "execute"
                            for tid in lineage_ids)
            reds = pipeline.get("gate_reds", execute.get("gate_reds"))
            for candidate in tasks.values():
                inputs = candidate.get("inputs") or []
                constraints = candidate.get("constraints") or {}
                target = constraints.get("review_for") or (inputs[0] if inputs else None)
                if candidate.get("role") == "review" and isinstance(target, str) and target in lineage_ids:
                    verdict = candidate.get("review_verdict") or (candidate.get("result") or {}).get("verdict")
                    if verdict in ("approve", "request_changes"):
                        reviews.append(verdict)
        accepted = bool(execute.get("merged_into")) if execute is not None else None
        own = root_runs.get(root_id, [])
        own_tokens=[REDACTED] for item in own]
        own_usd = [item.get("usd") for item in own if item.get("usd") is not None]
        own_latency = [item.get("duration_s") for item in own if item.get("duration_s") is not None]
        own_calls = [item.get("tool_calls", item.get("calls")) for item in own
                     if item.get("tool_calls", item.get("calls")) is not None]
        tier = row.get("tier")
        executor = row.get("executor") or row.get("executor_id")
        complexity = (execute or task).get("complexity")
        context = row["context"]
        result.append({
            **row, "skills_used": list(context.get("skills_used") or []),
            "skills_selected": (list(context.get("skills_selected") or [])
                                if context.get("skills_selected") is not None else None),
            "skill_tokens_l2": context.get("skill_tokens_l2"), "lineage_root": root_id,
            "first_pass": (fixes == 0 and reds == 0
                           if fixes is not None and reds is not None else None),
            "fix_rounds": fixes, "gate_reds": reds,
            "review_request_changes": (sum(value == "request_changes" for value in reviews)
                                       if reviews else None),
            "accepted": accepted,
            "accepted_tokens": (sum(value for value in own_tokens if value is not None)
                                if accepted and any(value is not None for value in own_tokens) else None),
            "accepted_usd": sum(own_usd) if accepted and own_usd else None,
            "latency_s": sum(own_latency) if own_latency else None,
            "tool_calls": sum(own_calls) if own_calls else None,
            "role": row.get("role"),
            "task_class": attribution.task_class(execute or task) if (execute or task) else None,
            "band": attribution.band(complexity),
            "model": row.get("model") or attribution.model_of(executor, tier, cfg),
            "strategy": (strategy.derive(execute, tasks, waves_rows=[]).get("strategy")
                         if execute is not None else None),
            "repo": "orchestrator",
        })
    return result


def _metric_summary(rows):
    result = {"n": len(rows)}
    for metric in METRICS:
